-- 称号を足す: 公式ソロモードと Main 3 / Aux 3 の実績の称号 (botbreaker, rootaccess, sevensins, tristate)
alter table public.secure_rooms drop constraint if exists secure_rooms_host_badge_check;
alter table public.secure_rooms drop constraint if exists secure_rooms_guest_badge_check;
alter table public.secure_rooms
  add constraint secure_rooms_host_badge_check check (host_badge is null or host_badge in ('compiler','veteran','tactician','expert','architect','master','legend','ascended','underdog','underdogduo','tagmaster','perfectsync','chainer','flawless','grandmaster','platinum','puzzler','compuzzler','gambler','highroller','fortune','regular','weeklylegend','conqueror','deicide','blindspot','botbreaker','rootaccess','sevensins','tristate','m_darkness','m_death','m_fire','m_gravity','m_life','m_light','m_metal','m_plague','m_psychic','m_speed','m_spirit','m_water','m_apathy','m_hate','m_love','m_chaos','m_clarity','m_corruption','m_courage','m_fear','m_ice','m_luck','m_mirror','m_peace','m_smoke','m_time','m_war','m_assimilation','m_diversity','m_unity','m_ambush','m_envy','m_fulcrum','m_gluttony','m_greed','m_lust','m_momentum','m_nova','m_overwhelm','m_pride','m_sloth','m_wrath','m_flexible','m_inert','m_rigid')),
  add constraint secure_rooms_guest_badge_check check (guest_badge is null or guest_badge in ('compiler','veteran','tactician','expert','architect','master','legend','ascended','underdog','underdogduo','tagmaster','perfectsync','chainer','flawless','grandmaster','platinum','puzzler','compuzzler','gambler','highroller','fortune','regular','weeklylegend','conqueror','deicide','blindspot','botbreaker','rootaccess','sevensins','tristate','m_darkness','m_death','m_fire','m_gravity','m_life','m_light','m_metal','m_plague','m_psychic','m_speed','m_spirit','m_water','m_apathy','m_hate','m_love','m_chaos','m_clarity','m_corruption','m_courage','m_fear','m_ice','m_luck','m_mirror','m_peace','m_smoke','m_time','m_war','m_assimilation','m_diversity','m_unity','m_ambush','m_envy','m_fulcrum','m_gluttony','m_greed','m_lust','m_momentum','m_nova','m_overwhelm','m_pride','m_sloth','m_wrath','m_flexible','m_inert','m_rigid'));
